import{ae as m}from"./BfuTd02G.js";const e="https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=960&q=80",o="https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=800&q=80",g="Shaanxi Tuotaizhe Metal Technology Co., Ltd.",p="Founded in 2025 in Baoji High-tech Zone, Shaanxi Tuotaizhe Metal Technology Co, Ltd. is a tech-driven enterprise focusing on non-ferrous metals and alloy materials.",f="+8618220735352",b="+86 18220735352",y="titalife0917@gmail.com",k="http://beian.miit.gov.cn/",w="陕ICP备2026001012号",t=[{id:"cat-mountain-bike",label:"Titanium alloy mountain bikes and accessories"},{id:"cat-road-bike",label:"Titanium alloy road bikes and accessories"},{id:"cat-folding-bike",label:"Titanium alloy folding bikes and accessories"},{id:"cat-small-wheel-bike",label:"Titanium alloy small-wheel bikes and accessories"},{id:"cat-gravel-bike",label:"Titanium alloy gravel road bikes and accessories"}],v=t.map(a=>({...a})),n=[{id:"cat-mountain-bike",label:t[0].label,intro:"Lightweight Ti frames and components for trail and XC, engineered for durability and corrosion resistance in harsh environments.",products:[{title:"TIOK M2 27.5 Titanium Alloy Mountain Bike, 12-Speed High-End Titanium Alloy Bike",image:e},{title:"TIOK Titanium Alloy Mountain Bike, 27-speed Off-Road Hydraulic Disc Brakes, High Load Capacity for Long-Distance Riding",image:e}]},{id:"cat-road-bike",label:t[1].label,intro:"Road and endurance geometries with internal routing options, disc and rim-compatible lineups for club and elite riders.",products:[{title:"TIOKAR3 aerodynamic road bike with titanium alloy wheels, internal cable routing, hydraulic disc brakes, and integrated carbon fiber handlebars.",image:e},{title:"TIOK 22-inch 451 disc brake titanium alloy small wheel bicycle, city adult 11-speed flat handlebar road bike",image:e}]},{id:"cat-folding-bike",label:t[2].label,intro:"Compact fold designs for urban multimodal travel; titanium keeps weight low without sacrificing ride quality.",products:[{title:"TIOK Titanium Alloy Small Cloth Folding Bicycle Retro City 7-speed 16 inch Triple Folding Bicycle",image:e}]},{id:"cat-small-wheel-bike",label:t[3].label,intro:'451 and 16"–20" wheel platforms for city and travel; stable handling with premium small-wheel geometry.',products:[{title:"TIOK 22-inch 451 titanium alloy bicycle, small wheels, 11-speed urban adult, flat handlebars, road bike with hydraulic disc brakes.",image:e}]},{id:"cat-gravel-bike",label:t[4].label,intro:"Clearance for wide tires, mount points for racks and mudguards, optimized for mixed surfaces and long gravel events.",products:[{title:"TIOK Titanium Gravel Road Bike with Threshold Axle, Handlebars, 22-Speed Hydraulic Disc Brakes",image:e},{title:"TIOK Titanium Gravel Road Bike with Threshold Axles, Flat Handlebars, 22-Speed Hydraulic Disc Brakes",image:e}]}];function T(a,c){return n.find(i=>i.id===a)}const C=n.flatMap(a=>a.products),S=[{image:e,title:n[1].products[1].title},{image:e,title:n[0].products[0].title},{image:e,title:n[4].products[0].title}],H=["Founded in 2025 in Baoji High-tech Zone, Shaanxi Tuotaizhe Metal Technology Co., Ltd. is a tech-driven enterprise focusing on non-ferrous metals and alloy materials.",'We mainly engage in non-ferrous metal rolling processing, R&D and sales of new metal functional materials. Meanwhile, we are involved in metal products manufacturing, production and sales of titanium alloy bicycles, spare parts, outdoor products, titanium cups and kettles. We also conduct new material technology R&D and import & export trade. Relying on the industrial and location advantages of Baoji "China Titanium Valley", we take technological innovation as the core, provide customers with integrated solutions of metal material processing, product sales and technical services, and strive to achieve dual breakthroughs in market and technology in the metal technology field.'],x=o,B=[{id:"news-speaker-evaluation",title:"Main indicators of speakers and methods of evaluating speakers",excerpt:"The parameter of power is actually a basic parameter to measure the performance of a multimedia speaker, but because of the intentional avoidance of the manufacturer, in the description of many products, the power has become a meaningless parameter.",date:"2020-07-11",image:o,body:"The parameter of power is actually a basic parameter to measure the performance of a multimedia speaker, but because of the intentional avoidance of the manufacturer, in the description of many products, the power has become a meaningless parameter. In practice, consumers should look at rated power, sensitivity, and distortion together rather than peak marketing numbers alone."},{id:"news-drums-enlightenment",title:"Drums are a better weapon for musical enlightenment",excerpt:'A well-qualified development psychologist and a professor at Harvard University in the United States once said: "Among all the intelligences that individuals may have, musical intelligence is the earliest." There are two important functions of early childhood music education.',date:"2020-06-28",image:o,body:'A well-qualified development psychologist and a professor at Harvard University in the United States once said: "Among all the intelligences that individuals may have, musical intelligence is the earliest." There are two important functions of early childhood music education: cultivating rhythm and listening, and supporting social collaboration through ensemble play.'},{id:"news-drums-learning-guide",title:"Dry goods-how to learn drums",excerpt:`There are three keys to unlocking the treasure trove of human wisdom: one is a number, one is a letter, and the other is a musical note." Hugo's famous saying illustrates the importance of music education.`,date:"2020-06-28",image:o,body:`There are three keys to unlocking the treasure trove of human wisdom: one is a number, one is a letter, and the other is a musical note." Hugo's famous saying illustrates the importance of music education. For beginners, short daily practice with a metronome and basic stick control exercises often yields better results than occasional long sessions.`},{id:"news-synth-drum-sound",title:"How to make a drum sound using a synthesizer",excerpt:"Using drum kit sound material is a very easy task, and there are many websites on the market like Splice and Sounds.com that can provide a lot of resources.",date:"2020-06-28",image:o,body:"Using drum kit sound material is a very easy task, and there are many websites on the market like Splice and Sounds.com that can provide a lot of resources. Layer samples with subtle velocity variation and gentle EQ so programmed parts still feel organic alongside acoustic instruments."}];function I(a){var s,l,r;const i=((r=(l=(s=m().public)==null?void 0:s.site)==null?void 0:l.url)==null?void 0:r.replace(/\/$/,""))||"",d=i?[{rel:"canonical",href:`${i}${a==="/"?"/":a}`}]:[],u=i?[{property:"og:url",content:`${i}${a}`}]:[];return{link:d,og:u}}export{f as a,x as b,k as c,y as d,S as e,n as f,T as g,b as h,w as i,v as j,p as k,g as l,B as n,H as p,C as s,I as u};
